{"content": "import sys, io, re, urllib.request
from concurrent.futures import ThreadPoolExecutor
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

urls = [l.strip() for l in open('fac_urls.txt') if l.strip()]

def get(u):
    try:
        req = urllib.request.Request(u, headers={'User-Agent': 'Mozilla/5.0'})
        html = urllib.request.urlopen(req, timeout=25).read().decode('utf-8', 'ignore')
    except Exception as e:
        return (u, None, str(e))
    txt = re.sub(r'(?is)<(script|style)[^>]*>.*?</\1>', ' ', html)
    txt = re.sub(r'(?i)</(p|div|tr|li|h[1-6]|br)>', '\n', txt)
    txt = re.sub(r'(?i)</t[dh]>', ' | ', txt)
    txt = re.sub(r'<[^>]+>', '', txt)
    txt = txt.replace('&nbsp;', ' ').replace('&amp;', '&')
    txt = re.sub(r'[ \t\r\xa0]+', ' ', txt)
    lines = [l.strip() for l in txt.split('\n') if l.strip()]
    return (u, lines, None)

results = []
with ThreadPoolExecutor(max_workers=8) as ex:
    for u, lines, err in ex.map(get, urls):
        results.append((u, lines, err))

for u, lines, err in results:
    if err or not lines:
        print('ERR', u, err); continue
    joined = '\n'.join(lines)
    name = ''
    m = re.search(r'系统 ([^\-]+)--中文主页', joined)
    if m: name = m.group(1).strip()
    hits = [l for l in lines if re.search(r'数字经济|数字金融|平台经济|数据要素|数字技术|人工智能|机器学习|大数据', l) and len(l) < 300]
    if not hits:
        continue
    seen = set(); out = []
    for l in hits:
        if l not in seen:
            seen.add(l); out.append(l)
    print('#'*8, name, u)
    print('\n'.join(out[:14]))
    print()
